import{_ as t,o as a,c as n,a3 as i}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"ATLAS Terminal","description":"Terminal web ATLAS avec couleurs ANSI, SSH facultatif, thèmes Oh My Posh et police Nerd Font servie par le serveur.","frontmatter":{"title":"ATLAS Terminal","description":"Terminal web ATLAS avec couleurs ANSI, SSH facultatif, thèmes Oh My Posh et police Nerd Font servie par le serveur."},"headers":[],"relativePath":"fr/projects/atlas-plugins/terminal.md","filePath":"fr/projects/atlas-plugins/terminal.md","lastUpdated":1792840662000}'),s={name:"fr/projects/atlas-plugins/terminal.md"};function r(l,e,o,c,u,d){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="atlas-terminal" tabindex="-1">ATLAS Terminal <a class="header-anchor" href="#atlas-terminal" aria-label="Permalink to &quot;ATLAS Terminal&quot;">​</a></h1><p>ATLAS Terminal est un dépôt de plugin indépendant qui fournit un terminal web authentifié. Il propose les couleurs ANSI, une taille de police réglable, des thèmes Oh My Posh sélectionnables et une connexion SSH facultative vers une cible configurée côté serveur.</p><p>L’interface est disponible en allemand, en anglais et en français. Le choix de langue est enregistré dans le navigateur et peut être transmis dans l’URL avec le paramètre <code>language</code>.</p><h2 id="depot-et-installation" tabindex="-1">Dépôt et installation <a class="header-anchor" href="#depot-et-installation" aria-label="Permalink to &quot;Dépôt et installation&quot;">​</a></h2><ul><li>GitHub : <a href="https://github.com/rockbaer2007/atlas-terminal-plugin" target="_blank" rel="noreferrer">rockbaer2007/atlas-terminal-plugin</a></li><li>Page d&#39;installation : <a href="https://rockbaer2007.github.io/atlas-terminal-plugin/install.html" target="_blank" rel="noreferrer">Ajouter ATLAS Terminal</a></li><li>Manifeste du dépôt : <a href="https://raw.githubusercontent.com/rockbaer2007/atlas-terminal-plugin/main/repository.json" target="_blank" rel="noreferrer">repository.json</a></li><li>Version du plugin : <code>0.1.10</code></li></ul><p>Dans l&#39;Administration ATLAS, ouvrez <strong>Plugins → Ajouter un dépôt</strong>, choisissez <strong>Plugin</strong> et saisissez l&#39;URL du manifeste. Vérifiez le dépôt, puis installez le paquet du plugin. L&#39;hôte ATLAS doit fournir un backend Terminal compatible.</p><h2 id="fonctionnalites" tabindex="-1">Fonctionnalités <a class="header-anchor" href="#fonctionnalites" aria-label="Permalink to &quot;Fonctionnalités&quot;">​</a></h2><ul><li>terminal web avec couleurs ANSI</li><li>taille de police réglable localement</li><li>thèmes Oh My Posh sélectionnables pour les sessions Bash locales</li><li>la police Nerd Font Meslo LGM est servie par Home Assistant ; aucune installation locale n&#39;est nécessaire sur les clients</li><li>cible SSH facultative avec hôte, utilisateur, clé et fichier <code>known_hosts</code> configurés côté serveur</li><li>vérification de la clé d&#39;hôte maintenue ; le navigateur ne peut pas choisir une cible SSH arbitraire</li><li>interface versionnée séparément dans le dépôt du plugin</li><li>paramètres du jeton repliables : ils se ferment à la connexion et se rouvrent après la déconnexion ou la fin de la session</li><li>les sessions shell locales démarrent à la racine du système de fichiers <code>/</code> dans le conteneur ATLAS, au lieu de <code>/app</code> ; en SSH, le répertoire par défaut du serveur distant est conservé</li></ul><h2 id="installer-la-nerd-font" tabindex="-1">Installer la Nerd Font <a class="header-anchor" href="#installer-la-nerd-font" aria-label="Permalink to &quot;Installer la Nerd Font&quot;">​</a></h2><p>Placez <code>MesloLGMNerdFontMono-Regular.ttf</code> et <code>MesloLGMNerdFontMono-Bold.ttf</code> dans <code>/config/www/fonts/</code> ou directement dans <code>/config/www/</code>. Home Assistant les sert sous <code>/local/fonts/</code> ou <code>/local/</code>, et le terminal charge les fichiers de police depuis ces chemins.</p><h2 id="prerequis-et-securite" tabindex="-1">Prérequis et sécurité <a class="header-anchor" href="#prerequis-et-securite" aria-label="Permalink to &quot;Prérequis et sécurité&quot;">​</a></h2><p>Le dépôt contient l&#39;interface du plugin, mais <strong>ce n&#39;est ni un serveur SSH autonome ni un module complémentaire Home Assistant</strong>. L&#39;hôte ATLAS fournit le shell ainsi que les fonctions Supervisor et WebSocket. Depuis le plugin <code>0.1.10</code>, catalogue, paquet et manifeste déclarent l’App/runtime <code>&gt;=0.1.215 &lt;0.2.0</code>, l’hôte <code>administration-local</code> et Home Assistant <code>&gt;=2026.8</code>. L’ancienne valeur <code>&gt;=0.2.0-alpha.79</code> désignait le framework et était incorrecte dans <code>compatibility.atlas</code>. App et framework ont des identités de version distinctes.</p><p>Les descripteurs Terminal partagés existants peuvent conserver l’ancienne exigence. Sauvegardez d’abord HA et l’état partagé, puis corrigez uniquement l’erreur identifiée en vérifiant la révision actuelle. Conservez les activations, les autres exigences et toutes les autres entrées. Actualiser le dépôt ne modifie pas l’état enregistré. Les sauvegardes de restauration conservent leurs exigences ; ne les réécrivez pas sans vérification et ne contournez pas les contrôles de compatibilité. La correction ne migre ni jetons ni données du plugin. La police Meslo nécessite l’App/Add-on <code>0.1.214</code> ; le répertoire racine et les paramètres repliables du jeton nécessitent <code>0.1.215</code> ou ultérieure.</p><p>Le terminal est désactivé par défaut. Activez-le uniquement après avoir configuré sur l&#39;hôte ATLAS un jeton d&#39;accès aléatoire et robuste d&#39;au moins 32 caractères sûrs pour les URL. Le shell local s&#39;exécute avec les droits du processus ATLAS. En mode App/Add-on Home Assistant, les permissions Supervisor peuvent également autoriser des commandes <code>ha</code> d&#39;administration. Considérez donc l&#39;accès au terminal comme un accès administratif.</p><p>Le jeton reste dans le stockage local du navigateur et est transmis lors de la connexion via le sous-protocole WebSocket, jamais dans une URL. Les paramètres du jeton se replient à la connexion et se rouvrent après la déconnexion ou la fin de la session. Ils restent ouverts au premier chargement si aucun jeton n&#39;est enregistré. Les scripts du même site peuvent accéder à ce stockage. Utilisez le terminal uniquement dans un profil de navigateur de confiance.</p><h2 id="etat-et-licence" tabindex="-1">État et licence <a class="header-anchor" href="#etat-et-licence" aria-label="Permalink to &quot;État et licence&quot;">​</a></h2><p>Le plugin est indiqué comme <strong>expérimental</strong>, car il nécessite un backend ATLAS compatible. Il est distribué sous licence <a href="https://github.com/rockbaer2007/atlas-terminal-plugin/blob/main/LICENSE" target="_blank" rel="noreferrer">MIT</a>.</p>',17)])])}const h=t(s,[["render",r]]);export{m as __pageData,h as default};
